result:
*{
  box-sizing: border-box;
}
.detail_page{
  height: 100%;
  background-image: url('../../img/detailback.png');
  position: relative;
  background-repeat: no-repeat;
  padding: 1px;
  .bottom_back{
    position: absolute;
    bottom: 0;
    width: 100%;
    height: calc(100% - 555px);
    background: linear-gradient(180deg, #fff 0%, rgba(206,229,255,0.8) 100%);
    z-index: -1;
  }
  .detail_box{
    margin: 140px 320px 0;
    min-width: 1280px;
    height: calc(100% - 140px);
    display: flex;
    justify-content: space-between;
    .detail_left{
      width: 920px;
      height: 100%;
      background: #fff;
      box-shadow: 0px 4px 25px 0px #e9f0ff;
      padding: 40px 35px 0 40px;
      .detail_info{
        border-bottom: 1px solid #f0f0f0;
        .info_top{
          display: flex;
          justify-content: space-between;
          min-height: 22px;
          line-height: 22px;
          margin-bottom: 15px;
          .el-button{
            height: 30px;
            width: 80px;
          }
          .title{
            color: #000;
            font-family: '黑体';
            font-size: 20px;
            font-weight: bold;
          }
          .info_btn{
            display: flex;
          }
        }
        .info_middle{
          font-size: 14px;
          color: #333;
          span{
            display: inline-block;
            height: 22px;
            line-height: 22px;
            margin-bottom: 20px;
          }
          i{margin-right: 7px;font-weight: bold}
        }
        .info_footer{
          font-size: 14px;
          color: #666;
          line-height: 22px;
          margin-bottom: 15px;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          padding-right: 25px;
          position: relative;
          .text_btn{
            position: absolute;
            right: 0px;
            color: #1061ff;
            cursor: pointer;
          }
          i{
            font-style: normal;
          }
        }
      }
      .detail_content{
        height: calc(100% - 117px);
        padding: 20px;
        .iframe{
          width: 100%;
          height: 100%;
        }
      }
    }
    .detail_right{
      width: 335px;
      height: 100%;
      .resource_card{
        background: #fff;
        box-shadow: 0 4px 25px 0 #e9f0ff;
        padding: 18px;
        box-shadow: 0px 4px 25px 0px #e9f0ff;
        border-radius: 4px;
        .card_title{
          display: flex;
          align-items: center;
          font-size: 15px;
          line-height: 20px;
          font-family: '黑体';
          margin-bottom: 20px;
          img{margin-right: 10px;}
        }
        .card_content{
          .card_list_item{
            display: flex;
            justify-content: space-between;
            font-size: 14px;
            margin-bottom: 20px;
            cursor: pointer;
            &:hover{
              color: #1061ff;
            }
            &:last-child{
              margin-bottom: 0px
            }

            .item_left{
              width: calc(100% - 50px);
              white-space: nowrap;
              overflow: hidden;
              text-overflow: ellipsis;
              padding-right: 20px;
              .item_index{
                margin-right: 20px;
                color: #999;
                font-weight: bold;
                font-size: 16px;
              }
            }
            .item_right{
              width: 45px;
            }
            &:first-child{
              .item_index{
                color: #ffd02b;
              }
            }
            &:nth-child(2) {
              .item_index{
                color: #6ca3e2;
              }
            }
            &:nth-child(3) {
              .item_index{
                color: #d5a38e;
              }
            }
          }
        }
      }
    }
  }
}
